        assert_eq!(json["overlay"]["hot_write_count"], 1);
        assert_eq!(json["growth_domains"][0]["domain"], "tickets");
        assert_eq!(json["growth_domains"][0]["current_records"], 1);
        assert_eq!(json["growth_domains"][0]["payload_bytes"], 7);
